BEGIN;
DELETE FROM lab_capabilities WHERE partner_id IN (SELECT id FROM lab_partners WHERE tenant_id='1c0ca9f2-06f6-42d3-89e2-6ab6ff41f997' AND lk_number='LK-016-IDN');
DELETE FROM lab_partners WHERE tenant_id='1c0ca9f2-06f6-42d3-89e2-6ab6ff41f997' AND lk_number='LK-016-IDN';
COMMIT;
SELECT 'LK-016-IDN' AS lk, count(*) AS rows, count(*) FILTER (WHERE verified) AS verified FROM lab_capabilities c JOIN lab_partners p ON p.id=c.partner_id WHERE p.lk_number='LK-016-IDN';
